sys_script_client.script:
function onLoad() {
    //Type appropriate comment here, and begin script below
    var caseId = g_form.getUniqueValue(); // assume this scripts is on task form
    var ga = new GlideAjax('MSSTrusteesCallUtils');
    ga.addParam('sysparm_name', 'gettaskassigned');
    ga.addParam('sysparm_case_id', caseId);
    ga.getXMLAnswer(function(responce) {
        var assignedTotask = responce;
        //var assignedTocase = g_form.getValue('assigned_to');
        if (assignedTotask == g_user.userID) {
            g_form.setValue('assigned_to', '');
            g_form.clearMessages();
            g_form.addErrorMessage("Task assignee to cannot be the same as Case assignee to")
        }




    });
}
